type termWhere[Q psql.Filterable] struct {
	cols               termColumns
	ID                 psql.WhereMod[Q, string]
	CreatedAt          psql.WhereMod[Q, time.Time]
	UpdatedAt          psql.WhereMod[Q, time.Time]
	TermSetID          psql.WhereMod[Q, string]
	ParentID           psql.WhereNullMod[Q, string]
	Name               psql.WhereMod[Q, string]
	NormalizedName     psql.WhereMod[Q, string]
	Labels             psql.WhereMod[Q, types.JSON[map[string]string]]
	Synonyms           psql.WhereMod[Q, types.JSON[[]string]]
	Description        psql.WhereMod[Q, string]
	Color              psql.WhereNullMod[Q, string]
	SortOrder          psql.WhereMod[Q, int64]
	Path               psql.WhereMod[Q, string]
	MergedIntoID       psql.WhereNullMod[Q, string]
	AvailableAsKeyword psql.WhereMod[Q, bool]
	Deprecated         psql.WhereMod[Q, bool]
	Version            psql.WhereMod[Q, int64]
	R                  termWhereR[Q]
}

func (termWhere[Q]) AliasedAs(alias string) termWhere[Q] {
	return buildTermWhere[Q](buildTermColumns(alias))
}

func buildTermWhere[Q psql.Filterable](cols termColumns) termWhere[Q] {
	return termWhere[Q]{
		cols:               cols,
		ID:                 psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:          psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:          psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		TermSetID:          psql.Where[Q, string](cols.TermSetID.Expression),
		ParentID:           psql.WhereNull[Q, string](cols.ParentID.Expression),
		Name:               psql.Where[Q, string](cols.Name.Expression),
		NormalizedName:     psql.Where[Q, string](cols.NormalizedName.Expression),
		Labels:             psql.Where[Q, types.JSON[map[string]string]](cols.Labels.Expression),
		Synonyms:           psql.Where[Q, types.JSON[[]string]](cols.Synonyms.Expression),
		Description:        psql.Where[Q, string](cols.Description.Expression),
		Color:              psql.WhereNull[Q, string](cols.Color.Expression),
		SortOrder:          psql.Where[Q, int64](cols.SortOrder.Expression),
		Path:               psql.Where[Q, string](cols.Path.Expression),
		MergedIntoID:       psql.WhereNull[Q, string](cols.MergedIntoID.Expression),
		AvailableAsKeyword: psql.Where[Q, bool](cols.AvailableAsKeyword.Expression),
		Deprecated:         psql.Where[Q, bool](cols.Deprecated.Expression),
		Version:            psql.Where[Q, int64](cols.Version.Expression),
		R:                  termWhereR[Q]{cols: cols},
	}
}

// termWhereR holds the relationship-based filters of
// termWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type termWhereR[Q psql.Filterable] struct {
	cols termColumns
}

// HasIDRelationshipType filters parents that have a matching IDRelationshipType using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to RelationshipTypes).
func (w termWhereR[Q]) HasIDRelationshipType(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(RelationshipTypes.NameExpr()),
		sm.Where(RelationshipTypes.Columns.ID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasMergedInto filters parents that have a matching MergedInto using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Terms).
func (w termWhereR[Q]) HasMergedInto(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	// self-referential relation: alias the subquery table so the correlation
	// columns still reference the parent row rather than the subquery's own row.
	relTbl := Terms.Columns.AliasedAs("MergedInto")
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Terms.NameExpr().As("MergedInto")),
		sm.Where(relTbl.ID.EQ(w.cols.MergedIntoID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

